"package com.example.app.architecture;

import com.tngtech.archunit.lang.ArchRule;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;

public final class BoundedContextIsolationRules {

    private BoundedContextIsolationRules() {
    }

    public static ArchRule noCrossContextInternalAccess(String sourceContext, String targetContext) {
        String sourcePkg = "com.example.app." + sourceContext + "..";
        String targetRepoPkg = "com.example.app." + targetContext + ".repository..";
        String targetEntityPkg = "com.example.app." + targetContext + ".entity..";
        String targetDomainPkg = "com.example.app." + targetContext + ".domain..";
        return noClasses()
                .that().resideInAPackage(sourcePkg)
                .should().dependOnClassesThat()
                .resideInAnyPackage(targetRepoPkg, targetEntityPkg, targetDomainPkg)
                .because("bounded context '" + sourceContext + "' must not access internal repository, entity, "
                        + "or domain classes of '" + targetContext + "'")
                .allowEmptyShould(true);
    }
}
